const orig = require("./orig_proc.js");
const mine = require("./process_events.js");

let seed = 12345;
function rand() {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
}
function randInt(n) { return Math.floor(rand() * n); }

const ITEMS = ["a", "b", "c", "d"];
const IDS = ["o1", "o2", "o3", "o4", "o5", "x1", "x2"];

function randomInput() {
  const stock = {};
  for (const it of ITEMS) {
    if (rand() < 0.5) stock[it] = randInt(8);
  }
  const events = [];
  const n = randInt(40);
  for (let i = 0; i < n; i++) {
    const t = randInt(12);
    const ev = {};
    if (t <= 3) { ev.type = "order"; ev.id = IDS[randInt(IDS.length)]; ev.item = ITEMS[randInt(ITEMS.length)]; ev.qty = randInt(6) + 1; }
    else if (t <= 6) { ev.type = i === 0 ? "order" : "cancel"; ev.id = IDS[randInt(IDS.length)]; }
    else if (t <= 8) { ev.type = "ship"; ev.id = IDS[randInt(IDS.length)]; if (rand() < 0.5) ev.qty = randInt(5) + 1; }
    else if (t <= 9) { ev.type = "restock"; ev.item = ITEMS[randInt(ITEMS.length)]; ev.qty = randInt(6) + 1; }
    else if (t <= 10) { ev.type = "expire"; ev.id = IDS[randInt(IDS.length)]; }
    else { ev.type = i === 0 ? "order" : "bogus"; ev.id = "z"; }
    events.push(ev);
  }
  return { stock, events };
}

// Also include adversarial stress: many backorders filled/expired
function stressInput() {
  return {
    stock: { a: 2, b: 0 },
    events: [
      { type: "order", id: "o1", item: "a", qty: 1 },
      { type: "order", id: "o2", item: "a", qty: 5 },
      { type: "order", id: "o3", item: "b", qty: 3 },
      { type: "order", id: "o4", item: "b", qty: 3 },
      { type: "cancel", id: "o2" },
      { type: "restock", item: "b", qty: 10 },
      { type: "ship", id: "o1", qty: 1 },
      { type: "expire", id: "o3" },
      { type: "ship", id: "o3" },
      { type: "cancel", id: "o4" },
      { type: "ship", id: "o5" },
      { type: "restock", item: "a", qty: 2 },
    ],
  };
}

const N = 500000;
let mismatches = 0;
for (let i = 0; i < N; i++) {
  let input = (i % 7 === 0) ? stressInput() : randomInput();
  let A, B;
  try { A = orig.processEvents(JSON.parse(JSON.stringify(input))); } catch (e) { A = { THREW: String(e) }; }
  try { B = mine.processEvents(JSON.parse(JSON.stringify(input))); } catch (e) { B = { THREW: String(e) }; }
  if (JSON.stringify(A) !== JSON.stringify(B)) {
    mismatches++;
    if (mismatches <= 5) {
      console.log("MISMATCH for input:", JSON.stringify(input));
      console.log("  orig:", JSON.stringify(A));
      console.log("  mine:", JSON.stringify(B));
    }
  }
}
console.log("Ran", N, "differential cases; mismatches:", mismatches);

