    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
